#include <DHTesp.h>
#include <WiFi.h>

#define WIFI_NAME "WIFI_ADM_CFP402"
#define WIFI_PASS "ac4ce0ss2"
#define pinOut 15


DHTesp dhtSensor;

void ConnectWifi()
{
  Serial.println("Connecting to Wifi...")
  int attempts = 0;
  while (WiFi.status() != WL_CONNECTED && attemps < 20)
  {
    WiFi.begin(WIFI_NAME, WIFI_PASS, 6);
    delay(500);
    Serial.print(".");
    attempts++;
  }
  if (WiFi.status() != WL_CONNECTED)
  {
    Serial.println("\nFailed to connect to WiFi.");
  } else
  {
    Serial.println("\nConnect to WiFi");
  }
}

void setup()
{
  Serial.begin(115200);
  Serial.println("ESP32 and DHT Sensor");
  dhtSensor.setup(pinOut, DHTesp::DHT22);
  ConnectWifi();
}


void loop()
{
  TempAndHumidity data = dhtSensor.getTempAndHumidity();
  float temp = data.temperature;
  int hum = data.humidity;

  Serial.println(temp);
  Serial.println(hum);
  delay(1000);
}using System;
using System.Collections.Generic;

public interface IObserver
{
    void Update(string message);
}

public interface ISubject
{
    void RegisterObserver(IObserver observer);
    void RemoveObserver(IObserver observer);
    void NotifyObservers(string message);
}

public class Subject : ISubject
{
    private List<IObserver> _observers = new List<IObserver>();

    public void RegisterObserver(IObserver observer)
    {
        if (!_observers.Contains(observer))
        {
            _observers.Add(observer);
        }
    }

    public void RemoveObserver(IObserver observer)
    {
        if (_observers.Contains(observer))
        {
            _observers.Remove(observer);
        }
    }

    public void NotifyObservers(string message)
    {
        foreach (var observer in _observers)
        {
            observer.Update(message);
        }
    }

    public void DoSomethingImportant()
    {
        Console.WriteLine("Subject: Estou fazendo algo importante!");
        NotifyObservers("Algo importante aconteceu!");
    }
}

public class ConcreteObserver : IObserver
{
    private string _name;

    public ConcreteObserver(string name)
    {
        _name = name;
    }

    public void Update(string message)
    {
        Console.WriteLine($"{_name} recebeu a mensagem: {message}");
    }
}

public class Program
{
    public static void Main(string[] args)
    {
        Subject subject = new Subject();

        ConcreteObserver observer1 = new ConcreteObserver("Observer 1");
        ConcreteObserver observer2 = new ConcreteObserver("Observer 2");

        subject.RegisterObserver(observer1);
        subject.RegisterObserver(observer2);

        subject.DoSomethingImportant();

        subject.RemoveObserver(observer1);
        subject.DoSomethingImportant();
    }
}

